.cr_de_number<-function(x,name,minimum=NULL,maximum=NULL){if(!is.numeric(x)||is.object(x)||length(x)!=1L||!is.null(dim(x))||!is.finite(x)||(!is.null(minimum)&&x<minimum)||(!is.null(maximum)&&x>maximum)) .cr_error('DECISION_ECONOMICS_INPUT',paste(name,'outside finite numeric domain'));as.numeric(x)}
.cr_de_text<-function(x,name){if(!is.character(x)||length(x)!=1L||is.na(x)||!nzchar(trimws(x))) .cr_error('DECISION_ECONOMICS_INPUT',paste(name,'must be nonempty text'));x}
.cr_de_sum<-function(x){v<-sum(unlist(x,use.names=FALSE));if(!is.finite(v)) .cr_error('NUMERICAL_FAILURE','Decision economics outside finite representation');v}
.cr_de_context<-function(profile,as_of,context){.cr_data_date(as_of,'as_of');.cr_data_required(profile,c('profile_id','version','known_at','currency'));for(k in c('profile_id','version','currency')) .cr_de_text(profile[[k]],k);if(.cr_data_date(profile$known_at,'known_at')>.cr_data_date(as_of,'as_of')) .cr_error('DECISION_FUTURE_INPUT','Profile must be known by decision date');ctx<-.cr_result(NULL,'decisioning.context',context=context)$context;if((!is.null(ctx$currency)&&ctx$currency!=profile$currency)||(!is.null(ctx$probability_measure)&&ctx$probability_measure!='PHYSICAL')) .cr_error('TARGET_MISMATCH','Physical offer economics and currency must match context');if(.cr_object(profile$target))for(key in c('horizon','time_unit','conditioning'))if(!is.null(ctx[[key]])&&!identical(ctx[[key]],profile$target[[key]])&&(!is.numeric(ctx[[key]])||!is.numeric(profile$target[[key]])||ctx[[key]]!=profile$target[[key]])) .cr_error('TARGET_MISMATCH','Context conflicts with declared target');ctx}
.cr_de_bound<-function(x){x$sha256<-.cr_hash(x);x}
.cr_de_target<-function(x,allowed_events='default'){.cr_data_required(x,c('event','horizon','time_unit','probability_measure','conditioning'));if(!(x$event%in%allowed_events)||x$time_unit!='days'||x$probability_measure!='PHYSICAL') .cr_error('TARGET_MISMATCH','Physical default target in days required');n<-.cr_de_number(x$horizon,'horizon',1);if(n!=floor(n)) .cr_error('TARGET_MISMATCH','Integer day horizon required');.cr_de_text(x$conditioning,'conditioning');invisible(NULL)}
.cr_de_offer<-function(row,ids,as_of,currency){.cr_data_required(row,c('offer_id','version','known_at','currency','subject_id','amount','tenor_days','assumption_reference'));for(k in c('offer_id','version','subject_id','assumption_reference')) .cr_de_text(row[[k]],k);if(row$offer_id%in%ids) .cr_error('DECISION_DUPLICATE','Unique versioned offer IDs required');if(.cr_data_date(row$known_at,'known_at')>.cr_data_date(as_of,'as_of')) .cr_error('DECISION_FUTURE_INPUT','Offer assumptions must be known by decision date');if(row$currency!=currency) .cr_error('TARGET_MISMATCH','Offer currency differs from profile');.cr_de_number(row$amount,'amount',0);n<-.cr_de_number(row$tenor_days,'tenor_days',1);if(n!=floor(n)) .cr_error('DECISION_ECONOMICS_INPUT','Integer tenor days required');c(ids,row$offer_id)}
.cr_de_sorted<-function(rows,key){if(length(rows))rows[order(vapply(rows,function(r)if(is.null(r[[key]]))''else r[[key]],''))]else rows}
compute_limit_frontier<-function(offer_candidates,constraint_profile,as_of,context=NULL){
 profile<-constraint_profile;ctx<-.cr_de_context(profile,as_of,context);.cr_data_required(profile,c('target','maximum_amount','maximum_ead','maximum_expected_loss','maximum_concentration','concentration_denominator','existing_group_exposure','tolerance'));.cr_de_target(profile$target)
 for(k in c('maximum_amount','maximum_ead','maximum_expected_loss','existing_group_exposure','tolerance')) .cr_de_number(profile[[k]],k,0)
 .cr_de_number(profile$maximum_concentration,'maximum_concentration',0,1);denominator<-.cr_de_number(profile$concentration_denominator,'concentration_denominator',0);if(denominator==0) .cr_error('DECISION_ECONOMICS_INPUT','Positive fixed post-decision concentration denominator required')
 rows<-.cr_data_rows(offer_candidates,'offer_candidates');ids<-character();out<-list();subject<-NULL
 for(row in .cr_de_sorted(rows,'offer_id')){ids<-.cr_de_offer(row,ids,as_of,profile$currency);if(!is.null(subject)&&row$subject_id!=subject) .cr_error('DECISION_SUBJECT','One subject per discrete limit frontier');subject<-row$subject_id;.cr_data_required(row,c('target','pd','lgd','ead','risk_conditioning','risk_reference','affordability_status','eligibility_status'))
 if(.cr_hash(row$target)!=.cr_hash(profile$target)||row$risk_conditioning!='CONDITIONAL_ON_THIS_OFFER') .cr_error('TARGET_MISMATCH','Offer-conditioned risk with shared target required');.cr_de_text(row$risk_reference,'risk_reference');pd<-.cr_de_number(row$pd,'pd',0,1);lgd<-.cr_de_number(row$lgd,'lgd');ead<-.cr_de_number(row$ead,'ead',0)
 if(!(row$affordability_status%in%c('AFFORDABLE','UNAFFORDABLE','UNKNOWN'))||!(row$eligibility_status%in%c('ELIGIBLE','INELIGIBLE','UNKNOWN'))) .cr_error('DECISION_ECONOMICS_INPUT','Explicit affordability and eligibility states required');if(!('affordability_maximum_amount'%in%names(row))) .cr_error('DATA_SCHEMA','Explicit nullable affordability cap required');cap<-row$affordability_maximum_amount;if(!is.null(cap)) .cr_de_number(cap,'affordability_maximum_amount',0)
 el<-.cr_de_sum(pd*lgd*ead);concentration<-.cr_de_sum(c(profile$existing_group_exposure,ead))/denominator;values<-c(AMOUNT=row$amount,EAD=ead,EXPECTED_LOSS=el,CONCENTRATION=concentration);bounds<-c(profile$maximum_amount,profile$maximum_ead,profile$maximum_expected_loss,profile$maximum_concentration);if(!is.null(cap)){values<-c(values,AFFORDABILITY_AMOUNT=row$amount);bounds<-c(bounds,cap)};slacks<-setNames(lapply(seq_along(values),function(i).cr_de_sum(c(bounds[i],-values[i]))),names(values));failures<-names(slacks)[vapply(slacks,function(s)s< -profile$tolerance,TRUE)];if(row$affordability_status!='AFFORDABLE'||is.null(cap))failures<-c(failures,'AFFORDABILITY_NOT_ESTABLISHED');if(row$eligibility_status!='ELIGIBLE')failures<-c(failures,'ELIGIBILITY_NOT_ESTABLISHED')
 out[[length(out)+1L]]<-list(offer_id=row$offer_id,version=row$version,offer_hash=.cr_hash(row),amount=row$amount,tenor_days=row$tenor_days,pd=pd,lgd=lgd,ead=ead,expected_loss=el,concentration=concentration,feasible=!length(failures),failures=as.list(failures),slacks=slacks,binding_constraints=as.list(names(slacks)[vapply(slacks,function(s)abs(s)<=profile$tolerance,TRUE)]))
 }
 feasible<-Filter(function(r)r$feasible,out);frontier<-list();for(r in feasible){dominated<-any(vapply(feasible,function(q)q$tenor_days==r$tenor_days&&q$amount>=r$amount&&q$expected_loss<=r$expected_loss&&(q$amount>r$amount||q$expected_loss<r$expected_loss),TRUE));if(!dominated)frontier[[length(frontier)+1L]]<-r$offer_id};maximum<-if(length(feasible))max(vapply(feasible,function(r)r$amount,0.))else NULL
 value<-.cr_de_bound(list(schema_version='1.0',kind='LimitFrontier',as_of=as_of,profile=profile,subject_id=subject,candidates=out,frontier_offer_ids=frontier,maximum_feasible_amount=maximum,status=if(length(feasible))'FEASIBLE'else'INFEASIBLE'))
 .cr_result(value,'decisioning.compute_limit_frontier','limit_frontier',ctx,diagnostics=.cr_empty_object(),limitations='Discrete candidate enumeration only; no interpolation, monotonic risk assumption or operative limit change. Concentration uses a supplied fixed post-decision denominator. Offer-conditioned risk is supplied, not inferred from baseline PD. Affordability and eligibility do not modify PD.')
}
compute_risk_based_price_grid<-function(quote_candidates,pricing_profile,as_of,context=NULL){
 profile<-pricing_profile;ctx<-.cr_de_context(profile,as_of,context);.cr_data_required(profile,c('default_timing','prepayment_timing','funding_treatment','selection_assumption'))
 if(profile$default_timing!='BEFORE_DUE'||profile$prepayment_timing!='AFTER_COUPON'||profile$funding_treatment!='DISCOUNT_CURVE_ONLY'||profile$selection_assumption!='QUOTE_CONDITIONED_INPUTS_NOT_CAUSAL') .cr_error('DECISION_PRICING_CONTRACT','Explicit event ordering and funding/selection contract required')
 rows<-.cr_data_rows(quote_candidates,'quote_candidates');ids<-character();out<-list()
 for(row in .cr_de_sorted(rows,'offer_id')){
 ids<-.cr_de_offer(row,ids,as_of,profile$currency);.cr_data_required(row,c('annual_rate','target','risk_conditioning','risk_reference','takeup_probability','takeup_reference','upfront_fee','origination_cost','offer_cost','periods'));.cr_de_target(row$target);quote_profile<-profile;quote_profile$target<-row$target;.cr_de_context(quote_profile,as_of,ctx)
 if(row$target$horizon!=row$tenor_days||row$risk_conditioning!='CONDITIONAL_ON_THIS_ACCEPTED_QUOTE') .cr_error('TARGET_MISMATCH','Quote lifetime target and accepted-quote risk conditioning required');for(k in c('risk_reference','takeup_reference')) .cr_de_text(row[[k]],k);rate<-.cr_de_number(row$annual_rate,'annual_rate',0);takeup<-.cr_de_number(row$takeup_probability,'takeup_probability',0,1);for(k in c('upfront_fee','origination_cost','offer_cost')) .cr_de_number(row[[k]],k,0)
 periods<-.cr_data_rows(row$periods,'periods');if(!length(periods)) .cr_error('DECISION_PRICING_CONTRACT','Complete amortization calendar required');outstanding<-as.numeric(row$amount);survival<-1;previous<-as_of;cash<-list();contributions<-c(-outstanding,row$upfront_fee,-row$origination_cost);el_terms<-numeric();default_mass<-prepayment_mass<-0;discount_by_date<-setNames(list(1),as_of)
 for(p in periods){.cr_data_required(p,c('payment_date','scheduled_principal','conditional_default_probability','conditional_prepayment_probability','lgd','recovery_date','payment_discount_factor','recovery_discount_factor','servicing_cost','prepayment_fee'));end<-.cr_data_date(p$payment_date,'payment_date');start<-.cr_data_date(previous,'previous');recovery_date<-.cr_data_date(p$recovery_date,'recovery_date');if(end<=start||recovery_date<end) .cr_error('DECISION_PRICING_CONTRACT','Increasing payment dates and recovery after endpoint required');principal<-.cr_de_number(p$scheduled_principal,'scheduled_principal',0);if(principal>outstanding+1e-12*max(1,row$amount)) .cr_error('DECISION_PRICING_CONTRACT','Scheduled principal cannot exceed opening balance');principal<-min(principal,outstanding)
 qd<-.cr_de_number(p$conditional_default_probability,'conditional_default_probability',0,1);qp<-.cr_de_number(p$conditional_prepayment_probability,'conditional_prepayment_probability',0,1);if(qd+qp>1) .cr_error('DECISION_PRICING_CONTRACT','Default and prepayment are mutually exclusive conditional hazards');lgd<-.cr_de_number(p$lgd,'lgd');df<-.cr_de_number(p$payment_discount_factor,'payment_discount_factor',0);rdf<-.cr_de_number(p$recovery_discount_factor,'recovery_discount_factor',0);if(df==0||rdf==0) .cr_error('DECISION_PRICING_CONTRACT','Positive date-specific funding discount factors required')
 for(pair in list(list(p$payment_date,df),list(p$recovery_date,rdf))){when<-pair[[1]];factor<-pair[[2]];if(!is.null(discount_by_date[[when]])&&discount_by_date[[when]]!=factor) .cr_error('DECISION_PRICING_CONTRACT','Same cash date must use same funding discount factor');discount_by_date[[when]]<-factor}
 cost<-.cr_de_number(p$servicing_cost,'servicing_cost',0);fee<-.cr_de_number(p$prepayment_fee,'prepayment_fee',0);dm<-survival*qd;pm<-survival*qp;remaining<-survival*(1-qd-qp);coupon<-.cr_de_sum(outstanding*rate*as.numeric(end-start)/365);interest<-(survival-dm)*coupon;principal_cash<-pm*outstanding+remaining*principal;prepay_cash<-pm*fee;servicing<-survival*cost;net_recovery<-dm*outstanding*(1-lgd);discounted_loss<-dm*outstanding*lgd*rdf;pv<-.cr_de_sum(c((interest+principal_cash+prepay_cash-servicing)*df,net_recovery*rdf));contributions<-c(contributions,pv);el_terms<-c(el_terms,discounted_loss)
 cash[[length(cash)+1L]]<-list(payment_date=p$payment_date,recovery_date=p$recovery_date,opening_survival=survival,default_mass=dm,prepayment_mass=pm,closing_survival=remaining,opening_principal=outstanding,coupon_if_nondefault=coupon,expected_interest=interest,expected_principal=principal_cash,expected_prepayment_fee=prepay_cash,expected_servicing_cost=servicing,expected_net_recovery=net_recovery,discounted_net_cashflow=pv,discounted_expected_loss=discounted_loss);default_mass<-default_mass+dm;prepayment_mass<-prepayment_mass+pm;survival<-remaining;outstanding<-max(0,outstanding-principal);previous<-p$payment_date
 }
 if(as.numeric(.cr_data_date(previous,'previous')-.cr_data_date(as_of,'as_of'))!=row$tenor_days||outstanding>1e-12*max(1,row$amount)) .cr_error('DECISION_PRICING_CONTRACT','Full surviving amortization and calendar aligned to tenor required');booked_npv<-.cr_de_sum(contributions);per_offer<-.cr_de_sum(c(takeup*booked_npv,-row$offer_cost));el<-.cr_de_sum(el_terms)
 out[[length(out)+1L]]<-list(offer_id=row$offer_id,version=row$version,offer_hash=.cr_hash(row),amount=row$amount,tenor_days=row$tenor_days,annual_rate=rate,target=row$target,takeup_probability=takeup,lifetime_pd=default_mass,prepayment_probability=prepayment_mass,terminal_performing_probability=survival,conditional_booked_npv=booked_npv,expected_npv_per_offer=per_offer,conditional_discounted_expected_loss=el,expected_loss_per_offer=takeup*el,booked_break_even=booked_npv>=0,offer_break_even=per_offer>=0,cashflows=cash)
 }
 value<-.cr_de_bound(list(schema_version='1.0',kind='PriceGrid',as_of=as_of,profile=profile,candidates=out))
 .cr_result(value,'decisioning.compute_risk_based_price_grid','price_grid',ctx,diagnostics=.cr_empty_object(),limitations='Supplied quote-conditioned default/prepayment hazards and takeup assumptions; no causal price elasticity is estimated. Fixed simple ACT/365F coupon; default before due misses coupon and exposes opening principal, prepayment after coupon returns remaining principal. Servicing charged on opening survivors. Funding enters only through supplied date-specific discount factors, not a second interest expense. Full surviving amortization required; no hidden terminal value. Risk scenarios can change with price, so break-even flags do not imply a monotone or unique break-even rate.')
}
evaluate_treatment_candidates<-function(treatment_candidates,treatment_profile,as_of,context=NULL){
 profile<-treatment_profile;ctx<-.cr_de_context(profile,as_of,context);.cr_data_required(profile,c('subject_id','baseline_id','baseline_present_value','identification','allowed_actions'));for(k in c('subject_id','baseline_id')) .cr_de_text(profile[[k]],k);.cr_de_number(profile$baseline_present_value,'baseline_present_value');actions<-unlist(profile$allowed_actions,use.names=FALSE)
 if(profile$identification!='CONDITIONAL_SCENARIO_NOT_CAUSAL'||(length(actions)&&(!is.character(actions)||anyNA(actions)||any(!nzchar(actions))))) .cr_error('DECISION_TREATMENT_CONTRACT','Explicit allowed actions and noncausal conditional interpretation required')
 rows<-.cr_data_rows(treatment_candidates,'treatment_candidates');ids<-character();out<-list()
 for(row in .cr_de_sorted(rows,'treatment_id')){.cr_data_required(row,c('treatment_id','version','known_at','subject_id','currency','action','prediction_reference','support_status','affordability_status','eligibility_status','uptake_probability','offer_cost','accepted_upfront_cost','rejected_present_value','cashflows'));for(k in c('treatment_id','version','action','prediction_reference')) .cr_de_text(row[[k]],k);if(row$treatment_id%in%ids) .cr_error('DECISION_DUPLICATE','Unique treatment IDs required');ids<-c(ids,row$treatment_id)
 if(row$currency!=profile$currency||row$subject_id!=profile$subject_id) .cr_error('TARGET_MISMATCH','Treatment subject/currency must match profile');if(.cr_data_date(row$known_at,'known_at')>.cr_data_date(as_of,'as_of')) .cr_error('DECISION_FUTURE_INPUT','Treatment assumptions known by decision date required')
 if(!(row$support_status%in%c('SUPPORTED','UNSUPPORTED'))||!(row$affordability_status%in%c('AFFORDABLE','UNAFFORDABLE','NOT_REQUIRED','UNKNOWN'))||!(row$eligibility_status%in%c('ELIGIBLE','INELIGIBLE','UNKNOWN'))) .cr_error('DECISION_TREATMENT_CONTRACT','Explicit support/affordability/eligibility states required')
 for(k in c('offer_cost','accepted_upfront_cost')) .cr_de_number(row[[k]],k,0);uptake<-.cr_de_number(row$uptake_probability,'uptake_probability',0,1);reject<-.cr_de_number(row$rejected_present_value,'rejected_present_value');flows<-.cr_data_rows(row$cashflows,'cashflows');fids<-character();pv<-nominal<-numeric()
 for(f in flows){.cr_data_required(f,c('cashflow_id','date','expected_recovery','expected_cost','discount_factor'));.cr_de_text(f$cashflow_id,'cashflow_id');if(f$cashflow_id%in%fids||.cr_data_date(f$date,'date')<.cr_data_date(as_of,'as_of')) .cr_error('DECISION_TREATMENT_CONTRACT','Unique future/as-of conditional cash flows required');fids<-c(fids,f$cashflow_id);recovery<-.cr_de_number(f$expected_recovery,'expected_recovery',0);cost<-.cr_de_number(f$expected_cost,'expected_cost',0);df<-.cr_de_number(f$discount_factor,'discount_factor',0);if(df==0) .cr_error('DECISION_TREATMENT_CONTRACT','Positive discount factor required');nominal<-c(nominal,recovery-cost);pv<-c(pv,(recovery-cost)*df)}
 reasons<-character();if(!(row$action%in%actions))reasons<-c(reasons,'ACTION_NOT_ALLOWED');if(row$support_status!='SUPPORTED')reasons<-c(reasons,'UNSUPPORTED_PREDICTION');if(!(row$affordability_status%in%c('AFFORDABLE','NOT_REQUIRED')))reasons<-c(reasons,'AFFORDABILITY_NOT_ESTABLISHED');if(row$eligibility_status!='ELIGIBLE')reasons<-c(reasons,'ELIGIBILITY_NOT_ESTABLISHED');supported<-row$support_status=='SUPPORTED';conditional<-if(supported).cr_de_sum(c(pv,-row$accepted_upfront_cost))else NULL;expected<-if(supported).cr_de_sum(c(uptake*conditional,(1-uptake)*reject,-row$offer_cost))else NULL
 out[[length(out)+1L]]<-list(treatment_id=row$treatment_id,version=row$version,treatment_hash=.cr_hash(row),feasible=!length(reasons),failures=as.list(reasons),nominal_net_recovery=if(supported).cr_de_sum(nominal)else NULL,accepted_present_value=conditional,expected_present_value=expected,scenario_difference_from_baseline=if(supported).cr_de_sum(c(expected,-profile$baseline_present_value))else NULL)
 }
 feasible<-Filter(function(r)r$feasible,out);if(length(feasible))feasible<-feasible[order(-vapply(feasible,function(r)r$expected_present_value,0.),vapply(feasible,function(r)r$treatment_id,''))];ranking<-lapply(feasible,function(r)r$treatment_id)
 value<-.cr_de_bound(list(schema_version='1.0',kind='TreatmentEvaluation',as_of=as_of,profile=profile,candidates=out,feasible_ranking=ranking,status=if(length(ranking))'FEASIBLE'else'INFEASIBLE'))
 .cr_result(value,'decisioning.evaluate_treatment_candidates','treatment_evaluation',ctx,diagnostics=.cr_empty_object(),limitations='Action-conditioned cashflow scenarios, not identified causal treatment effects. Historical action selection and missing counterfactuals are not repaired. Expected recovery/cost amounts must already include within-acceptance timing and event probabilities; uptake is applied exactly once. Rejected value and baseline are explicit separate assumptions. Ranking is local and never executes a treatment.')
}
